mapper.select:
select st.St_Code as stCode, st.St_Title as stTitle, st.St_Type as stType, st.St_Handle_Type as stHandleType,
sd.D_Name as sfDName, mn.* from OA_Supervision_Feedback mn left join SYS_Department sd on sd.D_ID=mn.Sf_D_Id left join OA_Supervision_Task st on st.St_Id=mn.St_Id left join Pre_Project pro on pro.P_Id=st.P_Id
where 1=1
and mn.Te_Id = #{params.teId}
and st.P_Id=#{params.pId}
and mn.St_Id = #{params.stId}
and mn.Sf_D_Id = #{params.sfDId}
and mn.Sf_D_Person like concat('%',#{params.sfDPerson},'%')
and mn.Sf_D_Phone like concat('%',#{params.sfDPhone},'%')
and st.St_Code like concat('%',#{params.stCode},'%')
and st.St_Title like concat('%',#{params.stTitle},'%')
and likePname(#{params.pName},pro.P_Id)=true
and pro.P_Name like concat('%',#{params.pName},'%')
order by mn.${params.sortFiled} ${params.sortType}
order by ${params.sortSideFiled} ${params.sortType}
order by mn.Sf_Create_Time desc
